import { Router } from './router';

test('exact route match', () => {
  const router = new Router();
  const calls: string[] = [];
  router.addRoute('/home', () => calls.push('home'));
  router.addRoute('/about', () => calls.push('about'));
  router.navigate('/home');
  expect(calls).toEqual(['home']);
});

test('no match returns false', () => {
  const router = new Router();
  router.addRoute('/home', () => {});
  expect(router.navigate('/missing')).toBe(false);
});

test('single param extraction', () => {
  const router = new Router();
  let capturedParams: Record<string, string> = {};
  router.addRoute('/users/:id', (params) => { capturedParams = params; });
  router.navigate('/users/42');
  expect(capturedParams).toEqual({ id: '42' });
});

test('multiple params', () => {
  const router = new Router();
  let capturedParams: Record<string, string> = {};
  router.addRoute('/orgs/:org/repos/:repo', (params) => { capturedParams = params; });
  router.navigate('/orgs/acme/repos/widget');
  expect(capturedParams).toEqual({ org: 'acme', repo: 'widget' });
});

test('first matching route wins', () => {
  const router = new Router();
  const calls: string[] = [];
  router.addRoute('/items/:id', () => calls.push('param'));
  router.addRoute('/items/special', () => calls.push('exact'));
  router.navigate('/items/special');
  // First registered route should win
  expect(calls[0]).toBe('param');
});

test('navigate returns true on match', () => {
  const router = new Router();
  router.addRoute('/test', () => {});
  expect(router.navigate('/test')).toBe(true);
});
